    static long maxWidth(TreeNode root) {
        long best = 0;
        List<TreeNode> nodes = new ArrayList<>();
        List<Long> indexes = new ArrayList<>();
        nodes.add(root);
        indexes.add(0L);
        while (!nodes.isEmpty()) {
            long first = indexes.get(0);
            best = Math.max(best, indexes.get(indexes.size() - 1) - first + 1);
